package studio.jiayu.neo;
import org.json.*;
import android.util.Base64;
import android.graphics.BitmapFactory;
import java.util.*;
/** Drawing profiles stay in host state; only image bytes and provenance enter projects. */
final class ArtManager {
 final MainActivity a; volatile boolean busy;volatile ArtClient current;
 ArtManager(MainActivity a){this.a=a;}
 void cancel(){ArtClient c=current;if(c!=null)c.cancel();}
 static final String[] FIELDS={"id","name","protocol","endpoint","model","size","quality","keyHeader","keyPrefix","template","urlPath","b64Path","pollUrl","taskIdPath","statusPath","successStatus","failureStatus","modelsUrl"};
 void saveProfile(JSONObject input)throws Exception{
  if(busy)throw new Exception("请等待绘图任务结束再修改配置");JSONObject p=new JSONObject();for(String k:FIELDS)if(input.has(k))p.put(k,input.getString(k));ArtClient.validate(p,a.debug);
  String key=input.optString("key").trim();JSONObject old=null;try{old=a.byId("artProfiles",p.getString("id"));}catch(Exception ignored){}
  if(key.isEmpty()&&old!=null&&(!old.optString("endpoint").equals(p.optString("endpoint"))||!old.optString("keyHeader","Authorization").equals(p.optString("keyHeader","Authorization"))||!old.optString("keyPrefix","Bearer ").equals(p.optString("keyPrefix","Bearer "))))throw new Exception("更改服务地址或认证方式时请重新填写密钥");
  if(!key.isEmpty()){if(key.contains("\n")||key.contains("\r"))throw new Exception("密钥格式无效");for(String field:FIELDS)if(p.optString(field).contains(key))throw new Exception("请只在密钥栏填写密钥");a.vault.put("art:"+p.getString("id"),key);}
  a.upsert("artProfiles",p);synchronized(a){if(a.state.optString("artProfileId").isEmpty())a.state.put("artProfileId",p.getString("id"));a.saveState();}a.sendState();a.event("artProfileSaved",p.getString("id"));
 }
 JSONObject selected()throws Exception{synchronized(a){String id=a.state.optString("artProfileId");if(id.isEmpty())throw new Exception("请先添加并选择绘图 API");return new JSONObject(a.byId("artProfiles",id).toString());}}
 void settings(JSONObject q)throws Exception{if(busy||a.active!=null)throw new Exception("请先等待当前任务结束");synchronized(a){if(q.has("profileId")){a.byId("artProfiles",q.getString("profileId"));a.state.put("artProfileId",q.getString("profileId"));}if(q.has("allowAI"))a.state.put("artAllowAI",q.getBoolean("allowAI"));a.saveState();}a.sendState();}
 void delete(String id)throws Exception{if(busy||a.active!=null)throw new Exception("请等待当前任务结束");a.remove("artProfiles",id);a.vault.remove("art:"+id);synchronized(a){if(a.state.optString("artProfileId").equals(id)){a.state.remove("artProfileId");a.state.put("artAllowAI",false);a.saveState();}}a.sendState();a.event("artDeleted",id);}
 void detect(String id)throws Exception{if(busy)throw new Exception("请等待绘图任务结束");JSONObject p=new JSONObject(a.byId("artProfiles",id).toString());String key=a.vault.get("art:"+id);a.event("artStatus","正在检测绘图模型…");a.worker.execute(()->{try{
   String url=p.optString("modelsUrl");if(url.isEmpty()){if(p.optString("protocol").equals("custom"))throw new Exception("自定义协议请填写模型列表地址或直接输入模型 ID");url=ArtClient.base(p)+"/models";}
   java.net.URI origin=new java.net.URI(ArtClient.createUrl(p)),target=ArtClient.endpoint(url,a.debug);if(!Objects.equals(origin.getHost(),target.getHost())||origin.getPort()!=target.getPort()||!Objects.equals(origin.getScheme(),target.getScheme()))throw new Exception("模型检测必须使用同一 API 服务");
   JSONObject r=new ArtClient(a.debug).json(p,key,url,null,"");JSONArray data=r.getJSONArray("data"),ids=new JSONArray();TreeSet<String> found=new TreeSet<>();for(int i=0;i<data.length();i++){String model=data.getJSONObject(i).optString("id");if(model.matches("(?i).*(gpt-image|dall-e|nano-banana|flash-image|pro-image|qwen-image|wan.*image|grok-imagine-image|seedream|flux).*"))found.add(model);}for(String model:found)ids.put(model);synchronized(a){JSONObject actual=a.byId("artProfiles",id);actual.put("detectedModels",ids);a.saveState();}a.sendState();a.event("artModels",new JSONObject().put("id",id).put("models",ids));
  }catch(Exception e){a.event("artStatus",a.safeError(e));}});}
 void start(JSONObject q,boolean resume)throws Exception{
  if(a.projectChangeBusy())throw new Exception("请等待当前编辑、同步、构建或绘图任务结束");JSONObject staged=new JSONObject(a.byId("projects",resume?a.byId("artJobs",q.getString("jobId")).getString("projectId"):q.getString("projectId")).toString());busy=true;a.event("artBusy",true);
  a.worker.execute(()->{try{JSONObject result=generate(staged,q,false,resume?q.getString("jobId"):"");synchronized(a){JSONObject actual=a.byId("projects",staged.getString("id"));JSONObject before=new JSONObject(a.state.toString());try{if(!ProjectEdits.same(actual.getJSONObject("files"),result.getJSONObject("base")))throw new Exception("图片已保存，但代码同时发生修改，请从资源列表手动引用");JSONObject updated=ProjectEdits.apply(actual,actual.getJSONObject("files"),staged.getJSONObject("files"),"美术资源引用");a.replaceProject(updated);a.saveState();}catch(Exception e){a.state=before;throw e;}}a.sendState();a.event("artSaved",result.getJSONObject("asset"));if(q.optBoolean("preview",true))a.runOnUiThread(()->{try{if(a.localRunner!=null&&a.localRunner.dialog!=null)a.localRunner.dialog.dismiss();a.localRunner=new LocalRunner(a,a.byId("projects",staged.getString("id")));a.localRunner.start();}catch(Exception e){a.event("artStatus","图片已保存；项目预览未打开");}});
   }catch(Exception e){a.event("artStatus",a.safeError(e));}finally{busy=false;current=null;a.event("artBusy",false);a.sendState();}});
 }
 static String path(JSONObject staged,String requested)throws Exception{
  String path=requested.trim();if(path.isEmpty())path=(staged.optBoolean("cloudSource")?"public/":"")+"art-"+UUID.randomUUID().toString().substring(0,8)+".png";
  if(!path.matches("[A-Za-z0-9_/-]+\\.png")||!CloudFiles.path(path)||CloudFiles.excluded(path))throw new Exception("资源路径仅支持英文字母、数字、下划线和短横线，扩展名为 .png");if(staged.getJSONObject("files").has(path)||(staged.optJSONObject("binaryFiles")!=null&&staged.getJSONObject("binaryFiles").has(path)))throw new Exception("资源路径已存在，请使用新名称");return path;
 }
 static String reference(String path){return "/"+(path.startsWith("public/")?path.substring(7):path);}
 static void insert(JSONObject staged,JSONObject q,String path)throws Exception{
  String file=q.optString("referenceFile"),token=q.optString("placeholder");if(file.isEmpty())return;JSONObject files=staged.getJSONObject("files");if(!files.has(file))throw new Exception("引用文件不存在，请先创建该文件");String content=files.getString(file),url=reference(path);
  if(!token.isEmpty()){int at=content.indexOf(token);if(at<0||content.indexOf(token,at+token.length())>=0)throw new Exception("占位符必须在引用文件中精确出现一次");content=content.substring(0,at)+url+content.substring(at+token.length());}
  else{if(!file.endsWith(".html")||!content.contains("</body>"))throw new Exception("自动插入仅支持含 </body> 的 HTML；其他代码请填写唯一占位符");content=content.replace("</body>","<figure><img src=\""+url+"\" alt=\"生成的美术资源\" style=\"max-width:100%;height:auto\"></figure>\n</body>");}
  JSONObject next=ProjectEdits.apply(staged,files,new JSONObject().put(file,content),"美术引用暂存");staged.put("files",next.getJSONObject("files"));
 }
 JSONObject tool(JSONObject staged,JSONObject q)throws Exception{
  synchronized(a){if(!a.state.optBoolean("artAllowAI"))throw new Exception("绘图 API 尚未允许 AI 调用，请在美术资源中开启");}if(busy)throw new Exception("已有绘图任务正在进行");busy=true;a.event("artBusy",true);try{return generate(staged,q,true,"").getJSONObject("asset");}finally{busy=false;current=null;a.event("artBusy",false);a.sendState();}
 }
 void persist(JSONObject job)throws Exception{synchronized(a){a.upsert("artJobs",job);}a.event("artStatus",job.optString("message",job.optString("status")));}
 JSONObject generate(JSONObject staged,JSONObject q,boolean ai,String resume)throws Exception{
  JSONObject baseline=new JSONObject(staged.getJSONObject("files").toString()),job,p;String path;boolean isResume=!resume.isEmpty();
  if(isResume){synchronized(a){job=new JSONObject(a.byId("artJobs",resume).toString());p=new JSONObject(a.byId("artProfiles",job.getString("profileId")).toString());}if(job.optString("status").equals("saved"))throw new Exception("图片已保存，无需重复恢复");if(!job.optString("profileHash").equals(configHash(p)))throw new Exception("配置已改变；请恢复原服务配置后查询，避免向其他服务发送任务");path=path(staged,job.getString("path"));q=job.getJSONObject("args");}
  else{p=selected();if(p.optString("model").isEmpty())throw new Exception("请选择绘图模型");String prompt=q.optString("prompt").trim();if(prompt.isEmpty()||prompt.length()>6000)throw new Exception("绘图描述需为1至6000字符");path=path(staged,q.optString("path"));JSONObject candidate=new JSONObject(staged.toString());insert(candidate,q,path);JSONObject entries=CloudFiles.entries(candidate);long used=0;for(Iterator<String> it=entries.keys();it.hasNext();)used+=CloudFiles.bytes(entries.getJSONObject(it.next())).length;if(entries.length()>=300||used>3*1048576)throw new Exception("请先为项目预留1 MB资源空间，项目总容量最多4 MB");
   job=new JSONObject().put("id",UUID.randomUUID().toString()).put("profileId",p.getString("id")).put("profileHash",configHash(p)).put("projectId",staged.getString("id")).put("path",path).put("model",p.getString("model")).put("time",System.currentTimeMillis()).put("args",q).put("request",ArtClient.body(p,prompt)).put("status","submitting");}
  // Validate reference before a paid request or a resumed download.
  JSONObject preview=new JSONObject(staged.toString());insert(preview,q,path);String key=a.vault.get("art:"+p.getString("id"));if(key.isEmpty())throw new Exception("请保存绘图 API 密钥");current=new ArtClient(a.debug);ArtClient client=current;
  try{persist(job);boolean async=p.optString("protocol").equals("omnia")||!p.optString("pollUrl").isEmpty();JSONObject result;
   String task=job.optString("taskId");if(isResume&&task.isEmpty()&&!p.optString("protocol").equals("omnia"))throw new Exception("上次提交结果未知；此服务没有可恢复任务 ID，请先在服务商确认，未自动重新提交");
   if(task.isEmpty()){result=client.json(p,key,ArtClient.createUrl(p),job.getJSONObject("request"),job.getString("id"));if(async){task=ArtClient.value(result,p.optString("protocol").equals("omnia")?"id":p.optString("taskIdPath","id"));if(!task.matches("[A-Za-z0-9_-]{1,256}"))throw new Exception("提交后未取得有效任务 ID，请在服务商核对；不要重复生成");job.put("taskId",task).put("status","waiting").put("message","绘图任务已提交，等待生成…");persist(job);}}
   else result=client.json(p,key,ArtClient.pollUrl(p,task),null,"");
   if(async){long deadline=System.currentTimeMillis()+300000;while(true){client.check();if(p.optString("protocol").equals("omnia")&&!task.equals(result.optString("id")))throw new Exception("服务商返回的任务 ID 不一致，已停止保存");String status=ArtClient.value(result,p.optString("protocol").equals("omnia")?"status":p.optString("statusPath","status"));String success=p.optString("successStatus","succeeded");if(status.equals(success))break;String failures=p.optString("failureStatus","failed,canceled,cancelled");if(Arrays.asList(failures.split(",")).contains(status))throw new Exception("远端绘图任务已结束但未成功，请查看服务商任务记录");if(System.currentTimeMillis()>deadline)throw new Exception("等待超过5分钟；已保存任务，可继续查询，未重新生成");for(int i=0;i<15;i++){client.check();Thread.sleep(200);}result=client.json(p,key,ArtClient.pollUrl(p,task),null,"");}}
   synchronized(a){if(!job.optBoolean("usageRecorded")){JSONObject usage=ArtClient.usage(result);a.state.getJSONArray("usage").put(new JSONObject().put("id","art-"+job.getString("id")).put("time",System.currentTimeMillis()).put("source",Usage.source(p)).put("kind","image").put("images",1).put("projectId",staged.getString("id")).put("profileId",p.getString("id")).put("provider",p.optString("name")).put("model",p.optString("model")).put("status","ok").put("usage",usage));job.put("usageRecorded",true);a.upsert("artJobs",job);}}
   job.put("status","downloading").put("message","图片生成成功，正在保存到本地项目…");persist(job);byte[] bytes=client.image(p,result);client.check();BitmapFactory.Options info=new BitmapFactory.Options();info.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,info);
   JSONObject asset=new JSONObject().put("path",path).put("url",reference(path)).put("mime","image/png").put("width",info.outWidth).put("height",info.outHeight).put("bytes",bytes.length).put("sha256",CloudFiles.hash(bytes)).put("model",p.optString("model")).put("time",System.currentTimeMillis()).put("projectId",staged.getString("id"));
   synchronized(a){JSONObject before=new JSONObject(a.state.toString());try{JSONObject target=new JSONObject(a.byId("projects",staged.getString("id")).toString());path(target,path);JSONObject binaries=target.optJSONObject("binaryFiles");if(binaries==null)binaries=new JSONObject();binaries.put(path,Base64.encodeToString(bytes,Base64.NO_WRAP));target.put("binaryFiles",binaries);CloudFiles.entries(target);JSONArray assets=target.optJSONArray("artAssets");if(assets==null)assets=new JSONArray();assets.put(asset);target.put("artAssets",assets).put("updated",System.currentTimeMillis());a.replaceProject(target);job.put("status","saved").put("message","图片已保存，可离线预览和打包 APK").put("asset",asset);a.upsert("artJobs",job);a.saveState();staged.put("binaryFiles",new JSONObject(binaries.toString())).put("artAssets",new JSONArray(assets.toString()));}catch(Exception e){a.state=before;throw e;}}
   insert(staged,q,path);a.sendState();a.event("artAsset",asset);return new JSONObject().put("asset",asset).put("base",baseline);
  }catch(Exception e){job.put("status","paused").put("message",client.cancelled?"等待已停止，远端可能继续；可恢复原任务":"绘图未完成，可检查配置后恢复原任务");try{persist(job);}catch(Exception ignored){}if(e instanceof java.io.IOException&&!client.cancelled)throw new Exception("绘图网络请求未完成，远端结果可能未知；请恢复原任务，不要重复提交");throw e;}
 }
 static String configHash(JSONObject p)throws Exception{JSONObject canonical=new JSONObject();for(String k:FIELDS)canonical.put(k,p.optString(k));return CloudFiles.hash(canonical.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 JSONObject catalog()throws Exception{JSONObject p=selected();return new JSONObject().put("selectedModel",p.optString("model")).put("availableModels",p.optJSONArray("detectedModels")).put("enabled",a.state.optBoolean("artAllowAI")).put("message","generate_image 只发送绘图描述；每次1张，生成后保存PNG。不会发送项目代码。模型列表仅表示服务商列出，调用权限以实际结果为准。");}
}
